using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Newtonsoft.Json;
public static class B3RepairImport {
 public static object Run(){if(Application.isPlaying)throw new Exception("Wait for user Play to end");string a="Assets/Afrer_Seconds/05.Model/";AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var mats=AssetDatabase.FindAssets("t:Material",new[]{a+"Environment/B3/Materials",a+"Props/B3/Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).GroupBy(m=>m.name).ToDictionary(g=>g.Key,g=>g.First());var report=new List<object>();foreach(string cat in new[]{"Environment","Props"})foreach(string raw in Directory.GetFiles(a+cat+"/B3","BR_B3_*.fbx")){string f=raw.Replace('\\','/');var mi=(ModelImporter)AssetImporter.GetAtPath(f);mi.importAnimation=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var pair in mats){string name=pair.Key.StartsWith("B3M_")?"B4O_"+pair.Key.Substring(4):pair.Key;mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),name),pair.Value);}mi.SaveAndReimport();var src=AssetDatabase.LoadAssetAtPath<GameObject>(f);var rs=src.GetComponentsInChildren<MeshRenderer>(true);var bounds=new Bounds();bool first=true;int tri=0,degen=0;foreach(var mf in src.GetComponentsInChildren<MeshFilter>(true)){var m=mf.sharedMesh;var v=m.vertices;var ix=m.triangles;tri+=ix.Length/3;for(int i=0;i<ix.Length;i+=3)if(Vector3.Cross(v[ix[i+1]]-v[ix[i]],v[ix[i+2]]-v[ix[i]]).sqrMagnitude<1e-16f)degen++;foreach(var vv in v){var w=mf.transform.TransformPoint(vv);if(first){bounds=new Bounds(w,Vector3.zero);first=false;}else bounds.Encapsulate(w);}}report.Add(new{asset=f,name=src.name,size=new[]{bounds.size.x,bounds.size.y,bounds.size.z},center=new[]{bounds.center.x,bounds.center.y,bounds.center.z},triangles=tri,degenerate=degen,materials=rs.SelectMany(r=>r.sharedMaterials).Select(m=>m?m.name:"MISSING").Distinct().ToArray()});}string root=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));File.WriteAllText(root+"/SourceAssets/B3_StructureRepair/catalog.json",JsonConvert.SerializeObject(report,Formatting.Indented));return new{models=report.Count,activeScene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path,sceneDirty=UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty};}
}
